function terim(slug, title, category, definition, detail, example, borcama, related) {
  return {
    slug,
    title,
    category,
    definition: `${definition} Kapsamı, işlem türüne ve taraflar arasındaki koşullara göre farklılaşabilir.`,
    detail: `${detail} ${GENEL_NOT}`,
    example: `${example} ${ORNEK_NOT}`,
    borcama: `${borcama} ${BORCAMA_NOT}`,
    related,
  };
}

